const req = $json;
const phone = String(req.phone || '').replace(/\D/g, '');
const payload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: phone
};
if (req.template_name) {
  payload.type = 'template';
  payload.template = {
    name: req.template_name,
    language: { code: 'en' },
    components: [{
      type: 'body',
      parameters: (req.template_params || []).map(t => ({ type: 'text', text: String(t) }))
    }]
  };
} else {
  payload.type = 'text';
  payload.text = { preview_url: false, body: String(req.message || '') };
}
return [{ json: payload }];

const req = $('Send WhatsApp Reply').item.json;
const isTemplate = Boolean(req.template_name);
const metaResp = $json;
return [{
  json: {
    lead_id: req.lead_id || null,
    phone: req.phone || null,
    direction: 'outbound',
    content: req.message || ('[Template: ' + req.template_name + ']'),
    template_name: req.template_name || null,
    wa_message_id: metaResp?.messages?.[0]?.id || null,
    status: 'sent',
    sent_at: new Date().toISOString()
  }
}];
